import{_ as t}from"./chunks/theme-light.Cvg67qi0.js";import{_ as o,o as a,c as d,a3 as r}from"./chunks/framework.sni93WGf.js";const g=JSON.parse('{"title":"Writing in Blank","description":"","frontmatter":{},"headers":[],"relativePath":"guide/writing.md","filePath":"guide/writing.md"}'),n={name:"guide/writing.md"};function i(c,e,s,h,l,u){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="writing-in-blank" tabindex="-1">Writing in Blank <a class="header-anchor" href="#writing-in-blank" aria-label="Permalink to &quot;Writing in Blank&quot;">​</a></h1><p>Blank shows your text as it will look, not as markdown syntax. There are no toolbars: you format with <a href="./shortcuts">keyboard shortcuts</a> or by typing markdown, which Blank turns into formatting as you go.</p><img class="shot" src="'+t+'" alt="A document in Blank&#39;s light theme"><h2 id="format-as-you-type" tabindex="-1">Format as you type <a class="header-anchor" href="#format-as-you-type" aria-label="Permalink to &quot;Format as you type&quot;">​</a></h2><p>At the start of an empty line, type one of these to turn the line into a block:</p><table tabindex="0"><thead><tr><th>Type at the start of a line</th><th>Then</th><th>You get</th></tr></thead><tbody><tr><td><code>#</code> … <code>######</code></td><td>Space</td><td>Heading 1–6</td></tr><tr><td><code>-</code> <code>*</code> <code>+</code></td><td>Space</td><td>Bullet list</td></tr><tr><td><code>1.</code> (any number)</td><td>Space</td><td>Numbered list</td></tr><tr><td><code>&gt;</code></td><td>Space</td><td>Blockquote</td></tr><tr><td><code>---</code> <code>***</code> <code>___</code></td><td>Enter</td><td>Horizontal line</td></tr><tr><td><code>```</code> or <code>```lang</code></td><td>Enter</td><td>Code block</td></tr></tbody></table><p>Changed your mind? <code>Mod</code> <code>Z</code> right away gives you back the line as you typed it.</p><p>Inline markdown works too: <code>**bold**</code>, <code>*italic*</code>, <code>`code`</code>, <code>[title](url)</code> and plain URLs become formatting once you finish the word. See <a href="./autocorrect">Autocorrect</a> for everything Blank corrects.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Press <code>Mod</code> <code>Alt</code> <code>I</code> to add an image where the cursor is. In the dialog, press <em>Choose file…</em> (Tab gets you there) to pick a picture from your computer, give it a short description and press Enter. Blank puts the picture into the document itself, so your markdown file stays a single file you can move, copy and send without losing images. Large pictures are scaled down to a size that still prints well.</p><p>Instead of choosing a file, you can also type an address into the dialog, or type <code>![description](address)</code> and a space right in the text:</p><ul><li>a web address, like <code>https://example.com/map.png</code>,</li><li>a file next to your document, like <code>images/chart.png</code>, which appears once the document has been saved, since Blank needs to know its folder,</li><li>any file on your computer, like <code>/home/me/logo.png</code>.</li></ul><p>These images stay where they are and the document links to them.</p><p>To change or remove an image, put the cursor right before or after it and press <code>Mod</code> <code>Alt</code> <code>I</code> again.</p><p>Images are as wide as they are in the file, up to the width of the page, and <a href="./files#pdf">PDFs and Word documents</a> include them at that size.</p><h2 id="blank-remembers-your-document" tabindex="-1">Blank remembers your document <a class="header-anchor" href="#blank-remembers-your-document" aria-label="Permalink to &quot;Blank remembers your document&quot;">​</a></h2><p>Blank keeps what you write as you go, at least once a second and once more when you close the window, and restores it on the next start, together with the open file, the theme and the language. So you can close the window mid-thought without saving, and pick up right where you left off.</p><h2 id="save-open-and-export" tabindex="-1">Save, open and export <a class="header-anchor" href="#save-open-and-export" aria-label="Permalink to &quot;Save, open and export&quot;">​</a></h2><p>Your documents are plain markdown files: <code>Mod</code> <code>S</code> saves, <code>Mod</code> <code>O</code> opens, also Word documents. To share a piece, export it as a PDF with <code>Mod</code> <code>Alt</code> <code>P</code> or as a Word document with <code>Mod</code> <code>Alt</code> <code>W</code>. <a href="./files">Files &amp; formats</a> has everything about PDF and Word.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The top of the window shows the open file, <em>Untitled</em>, or the <a href="./files#open-word-documents">Word document</a> an untitled document was imported from. The bottom shows the word and character count, <a href="./spelling">spell check</a> while it is on, and the <a href="./autocorrect#language">language</a>.</p>',21)])])}const f=o(n,[["render",i]]);export{g as __pageData,f as default};
